/// <summary>
/// Reverse the ordered list
/// </summary>
private void reverseOrderedList()
{
    List reversedPalletRoundingPolicyItemCodeTypeOrderedList = new List(Types::Enum);
    ListEnumerator enumerator = this.getEnumerator() as ListEnumerator;

    while (enumerator.moveNext())
    {
        reversedPalletRoundingPolicyItemCodeTypeOrderedList.addStart(enumerator.current());
    }

    palletRoundingPolicyItemCodeTypeOrderedList = reversedPalletRoundingPolicyItemCodeTypeOrderedList;
}

