public static METPalletRoundingPolicyItemCodeTypeOrderedList newFromOrder(SortOrder _enumerateInOrder = SortOrder::Ascending)
{
    METPalletRoundingPolicyItemCodeTypeOrderedList orderedList = new METPalletRoundingPolicyItemCodeTypeOrderedList();
    orderedList.setEnumerateInOrder(_enumerateInOrder);
    return orderedList;
}

/// <summary>
/// Initialize the list with all the applicable values of <c>METItemTableGroup</c> enumeration in ascending order.
/// </summary>
protected void initializePalletRoundingPolicyItemCodeTypeOrderedList()
{
    palletRoundingPolicyItemCodeTypeOrderedList.addEnd(METItemTableGroup::Table);
    palletRoundingPolicyItemCodeTypeOrderedList.addEnd(METItemTableGroup::GroupId);
}
